package org.brightstats.model;
import java.util.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.stats.*;

/** Fixed mean/sum composites remain row functions; original observations are not overwritten. */
public final class DiagramProcess {
    private DiagramProcess(){}
    public record Composite(String node,String name,List<Integer> indicators,String aggregation,int column){public Composite{indicators=List.copyOf(indicators);}}
    public record Compiled(List<String> names,double[][] observations,PathProcess.Model model,List<Composite> composites,
                           List<PlsSem.Block> polynomialBlocks,List<PlsSem.Edge> polynomialPaths,List<NonlinearPls.Extension> extensions,
                           Map<String,Integer> identities,List<String> warnings){public Compiled{names=List.copyOf(names);observations=Matrices.copy(observations);composites=List.copyOf(composites);polynomialBlocks=List.copyOf(polynomialBlocks);polynomialPaths=List.copyOf(polynomialPaths);extensions=List.copyOf(extensions);identities=Collections.unmodifiableMap(new LinkedHashMap<>(identities));warnings=List.copyOf(warnings);}@Override public double[][] observations(){return Matrices.copy(observations);}}
    public static Compiled compile(Document document,List<String> columns,double[][] data){
        if(document.family()!=Family.PROCESS)throw new IllegalArgumentException("Choose a PROCESS diagram.");int width=Matrices.width(data,3);if(columns.size()!=width||new HashSet<>(columns).size()!=columns.size())throw new IllegalArgumentException("Use uniquely named data columns.");List<Node> variables=document.nodes().stream().filter(node->node.type()==ElementType.PROCESS_MODEL_LATENT_VARIABLE||node.type()==ElementType.PROCESS_MODEL_CONTROL_VARIABLE).toList();if(variables.size()<2||variables.size()>64)throw new IllegalArgumentException("Define 2–64 PROCESS composite/control nodes.");Map<String,Integer> identities=new LinkedHashMap<>();List<Composite> composites=new ArrayList<>();List<String> names=new ArrayList<>(columns);Set<String> labels=new HashSet<>();List<Integer> controls=new ArrayList<>();List<PlsSem.Block> blocks=new ArrayList<>();
        for(var node:variables){if(node.label().isBlank()||!labels.add(node.label()))throw new IllegalArgumentException("Name PROCESS composites uniquely.");List<Integer> selected=new ArrayList<>();var properties=node.properties();if(properties.has("column"))selected.add(column(properties.get("column"),columns));if(properties.has("columns"))for(var value:properties.getAsJsonArray("columns"))selected.add(column(value,columns));for(var link:document.links())if(link.type().measurement()&&(link.source().equals(node.id())||link.target().equals(node.id()))){var observed=document.node(link.source().equals(node.id())?link.target():link.source());if(!observed.type().observed())throw new IllegalArgumentException("Connect PROCESS composites to observed indicators.");selected.add(column(observed.properties().get("column"),columns));}if(selected.isEmpty()||new HashSet<>(selected).size()!=selected.size())throw new IllegalArgumentException("Bind distinct indicators to "+node.label()+".");String aggregation=DiagramModels.string(properties,"aggregation","MEAN");if(!aggregation.equals("MEAN")&&!aggregation.equals("SUM"))throw new IllegalArgumentException("This PROCESS composite contract supports fixed MEAN or SUM aggregation; estimated/standardized weights require an explicitly refitted scoring stage.");String name="Composite: "+node.label();int copy=2;while(names.contains(name))name="Composite: "+node.label()+" ["+(copy++)+"]";int index=names.size();names.add(name);identities.put(node.id(),composites.size());composites.add(new Composite(node.id(),name,selected,aggregation,index));blocks.add(new PlsSem.Block(node.label(),new int[]{index},PlsSem.Mode.A));if(node.type()==ElementType.PROCESS_MODEL_CONTROL_VARIABLE)controls.add(index);}
        if((long)data.length*names.size()>5_000_000)throw new IllegalArgumentException("PROCESS derived data exceeds five million cells.");double[][] derived=new double[data.length][names.size()];for(int row=0;row<data.length;row++){System.arraycopy(data[row],0,derived[row],0,width);for(var composite:composites){double value=0;int count=0;for(int indicator:composite.indicators){count++;value=composite.aggregation.equals("MEAN")?value+(data[row][indicator]-value)/count:value+data[row][indicator];}if(!Double.isFinite(value))throw new IllegalArgumentException("PROCESS composite exceeded numeric range.");derived[row][composite.column]=value;}}
        String source=DiagramModels.string(document.node(document.root()).properties(),"focalSource",null),target=DiagramModels.string(document.node(document.root()).properties(),"focalTarget",null);if(!identities.containsKey(source)||!identities.containsKey(target)||source.equals(target)||document.node(source).type()==ElementType.PROCESS_MODEL_CONTROL_VARIABLE||document.node(target).type()==ElementType.PROCESS_MODEL_CONTROL_VARIABLE)throw new IllegalArgumentException("Choose distinct focal source/outcome composite identities in the model settings.");
        List<PathProcess.Path> paths=new ArrayList<>();List<PlsSem.Edge> polynomialPaths=new ArrayList<>();Set<String> seen=new HashSet<>();for(var link:document.links())if(link.type().structural()){if(!identities.containsKey(link.source())||!identities.containsKey(link.target()))throw new IllegalArgumentException("PROCESS structural paths must connect composite/control nodes.");String key=link.source()+":"+link.target();if(!seen.add(key))throw new IllegalArgumentException("Duplicate PROCESS structural path.");int a=identities.get(link.source()),b=identities.get(link.target());paths.add(new PathProcess.Path(composites.get(a).column,composites.get(b).column));polynomialPaths.add(new PlsSem.Edge(a,b));}
        List<NonlinearPls.Extension> extensions=new ArrayList<>();for(var link:document.links())if(link.type()==ElementType.CONNECTION_FOR_PROCESS_MODERATION||link.type()==ElementType.CONNECTION_BETWEEN_PROCESS_QUADRATIC_EFFECT_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION){var term=DiagramModels.term(document,link,new HashSet<>());Integer outcome=identities.get(term.target());if(outcome==null)throw new IllegalArgumentException("PROCESS nonlinear effects require a composite outcome.");int[] factors=term.factors().stream().mapToInt(id->{Integer index=identities.get(id);if(index==null)throw new IllegalArgumentException("PROCESS nonlinear factors must be composite/control nodes.");return index;}).toArray();extensions.add(new NonlinearPls.Extension(outcome,factors));}
        for(var node:document.nodes())if(node.type()==ElementType.PROCESS_MODEL_QUADRATIC_EFFECT&&document.links().stream().noneMatch(link->link.source().equals(node.id())&&link.type().modifier()))throw new IllegalArgumentException("Attach PROCESS quadratic markers to a model path.");for(var node:document.nodes())if(node.type()==ElementType.GAUSSIAN_COPULA)throw new IllegalArgumentException("PROCESS copula markers require a separately supported corrected-equation workflow.");for(var link:document.links())if(link.type().name().contains("BETWEEN_GAUSSIAN_COPULA"))throw new IllegalArgumentException("PROCESS copula attachments require a separately supported corrected-equation workflow; they are not silently ignored.");
        var model=new PathProcess.Model(composites.get(identities.get(source)).column,composites.get(identities.get(target)).column,paths,controls.stream().mapToInt(Integer::intValue).toArray());return new Compiled(names,derived,model,composites,blocks,polynomialPaths,extensions,identities,List.of("PROCESS composite scores use declared fixed row-wise means/sums, not a latent measurement-error model. Original columns are retained in a separate derived matrix.","Case resampling of fixed row functions is equivalent to recomputing those functions on each draw. This statement does not cover estimated weights or data-wide standardization.","Nonlinear attachments are supplied explicitly to the polynomial workflow. They must not be dropped when choosing a linear path-analysis backend."));
    }
    private static int column(JsonElement value,List<String> columns){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Bind PROCESS indicators by dataset column name.");int index=columns.indexOf(value.getAsString());if(index<0)throw new IllegalArgumentException("PROCESS indicator column is missing.");return index;}
}
